100	func sortedKeys(m map[string]string) []string {
101		keys := make([]string, 0, len(m))
102		for k := range m {
103			keys = append(keys, k)
104		}
105		sort.Strings(keys)
106		return keys
107	}
108	
109	func makeSeriesID(name string, labels map[string]string) seriesID {
110		var b strings.Builder
111		for _, k := range sortedKeys(labels) {
112			v := labels[k]
113			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
114		}
115		return seriesID{name: name, sig: b.String()}
116	}
