118	// labelPair 是标签键值对字典序比较的单元。
119	type labelPair struct {
120		Key, Value string
121	}
122	
123	func sortedPairs(labels map[string]string) []labelPair {
124		keys := sortedKeys(labels)
125		pairs := make([]labelPair, len(keys))
126		for i, k := range keys {
127			pairs[i] = labelPair{Key: k, Value: labels[k]}
128		}
129		return pairs
130	}
131	
132	func compareLabelPairs(a, b []labelPair) int {
133		n := len(a)
134		if len(b) < n {
135			n = len(b)
136		}
137		for i := 0; i < n; i++ {
138			if a[i].Key != b[i].Key {
139				return strings.Compare(a[i].Key, b[i].Key)
140			}
141			if a[i].Value != b[i].Value {
142				return strings.Compare(a[i].Value, b[i].Value)
143			}
144		}
145		switch {
146		case len(a) < len(b):
147			return -1
148		case len(a) > len(b):
149			return 1
150		}
151		return 0
152	}
