154	var (
155		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
156		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
157	)
