159	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
160	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
161	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
162		top, ok, lerr := decodeTopValue(line)
163		if lerr != nil {
164			return nil, lerr
165		}
166		switch ok {
167		case '[':
168			var items []json.RawMessage
169			if err := json.Unmarshal(top, &items); err != nil {
170				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
171			}
172			return s.ingestItems(items)
173		case '{':
174			return s.queryFromObject(top)
175		default:
176			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
177		}
178	}
179	
180	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
181	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
182	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
183		top, ok, lerr := decodeTopValue(line)
184		if lerr != nil {
185			return nil, lerr
186		}
187		if ok != '[' {
188			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
189		}
190		var items []json.RawMessage
191		if err := json.Unmarshal(top, &items); err != nil {
192			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
193		}
194		return s.ingestItems(items)
195	}
196	
197	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
198	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
199		top, ok, lerr := decodeTopValue(line)
200		if lerr != nil {
201			return nil, lerr
202		}
203		if ok != '{' {
204			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
205		}
206		return s.queryFromObject(top)
207	}
208	
209	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
210	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
211	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
212		dec := json.NewDecoder(strings.NewReader(line))
213		var top json.RawMessage
214		if err := dec.Decode(&top); err != nil {
215			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
216		}
217		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
218		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
219			if err == nil {
220				err = fmt.Errorf("unexpected content after the JSON value")
221			}
222			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
223		}
224		trimmed := strings.TrimSpace(string(top))
225		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
226			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
227		}
228		return top, trimmed[0], nil
229	}
