231	type parsedSample struct {
232		name   string
233		ts     int64
234		value  float64
235		labels map[string]string
236	}
237	
238	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
239	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
240	func parseSample(raw json.RawMessage) (parsedSample, error) {
241		var p parsedSample
242		p.labels = map[string]string{}
243		dec := json.NewDecoder(bytes.NewReader(raw))
244		dec.UseNumber()
245	
246		tok, err := dec.Token()
247		if err != nil {
248			return p, err
249		}
250		if d, ok := tok.(json.Delim); !ok || d != '{' {
251			return p, fmt.Errorf("each sample must be a JSON object")
252		}
253	
254		present := make(map[string]bool)
255		for dec.More() {
256			keyTok, err := dec.Token()
257			if err != nil {
258				return p, err
259			}
260			key := keyTok.(string)
261			switch key {
262			case "name", "timestamp", "value", "labels":
263			default:
264				return p, fmt.Errorf("unknown field %q", key)
265			}
266			if present[key] {
267				return p, fmt.Errorf("duplicate field %q", key)
268			}
269			present[key] = true
270	
271			switch key {
272			case "name":
273				t, err := dec.Token()
274				if err != nil {
275					return p, err
276				}
277				s, ok := t.(string)
278				if !ok {
279					return p, fmt.Errorf(`field "name" must be a string`)
280				}
281				if s == "" {
282					return p, fmt.Errorf(`field "name" must be a non-empty string`)
283				}
284				p.name = s
285			case "timestamp":
286				n, err := nextJSONNumber(dec, "timestamp")
287				if err != nil {
288					return p, err
289				}
290				v, err := parseJSONInt(n)
291				if err != nil {
292					return p, fmt.Errorf(`field "timestamp": %s`, err)
293				}
294				p.ts = v
295			case "value":
296				n, err := nextJSONNumber(dec, "value")
297				if err != nil {
298					return p, err
299				}
300				v, err := parseFiniteFloat(n)
301				if err != nil {
302					return p, fmt.Errorf(`field "value": %s`, err)
303				}
304				p.value = v
305			case "labels":
306				t, err := dec.Token()
307				if err != nil {
308					return p, err
309				}
310				d, ok := t.(json.Delim)
311				if !ok || d != '{' {
312					return p, fmt.Errorf(`field "labels" must be an object of string keys to string values`)
313				}
314				labels := map[string]string{}
315				for dec.More() {
316					labelKeyTok, err := dec.Token()
317					if err != nil {
318						return p, err
319					}
320					labelKey := labelKeyTok.(string)
321					if labelKey == "" {
322						return p, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
323					}
324					valTok, err := dec.Token()
325					if err != nil {
326						return p, err
327					}
328					labelVal, ok := valTok.(string)
329					if !ok {
330						return p, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
331					}
332					if _, dup := labels[labelKey]; dup {
333						return p, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
334					}
335					labels[labelKey] = labelVal
336				}
337				if _, err := dec.Token(); err != nil { // 消耗 '}'
338					return p, err
339				}
340				p.labels = labels
341			}
342		}
343		if _, err := dec.Token(); err != nil { // 消耗 '}'
344			return p, err
345		}
346		if _, err := dec.Token(); err != io.EOF {
347			if err == nil {
348				return p, fmt.Errorf("unexpected content after the sample object")
349			}
350			return p, err
351		}
352	
353		for _, field := range []string{"name", "timestamp", "value"} {
354			if !present[field] {
355				return p, fmt.Errorf("missing required field %q", field)
356			}
357		}
358		return p, nil
359	}
360	
361	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
362		t, err := dec.Token()
363		if err != nil {
364			return "", err
365		}
366		n, ok := t.(json.Number)
367		if !ok {
368			return "", fmt.Errorf(`field %q must be a JSON number`, field)
369		}
370		return n, nil
371	}
372	
373	func parseJSONInt(n json.Number) (int64, error) {
374		s := string(n)
375		if !jsonIntegerRE.MatchString(s) {
376			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
377		}
378		v, err := strconv.ParseInt(s, 10, 64)
379		if err != nil {
380			return 0, fmt.Errorf("must be within int64 range")
381		}
382		return v, nil
383	}
384	
385	func parseFiniteFloat(n json.Number) (float64, error) {
386		s := string(n)
387		if !jsonNumberRE.MatchString(s) {
388			return 0, fmt.Errorf("must be a JSON number")
389		}
390		v, err := strconv.ParseFloat(s, 64)
391		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
392			return 0, fmt.Errorf("must be a finite number representable as float64")
393		}
394		return v, nil
395	}
