397	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
398	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
399		type pending struct {
400			id  seriesID
401			ref SeriesRef
402			ts  int64
403			val float64
404		}
405	
406		added := 0
407		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
408		seen := make(map[seriesID]map[int64]float64)
409		// 仅记录需要落盘的新增点；校验全部通过后才提交。
410		commits := make([]pending, 0, len(items))
411	
412		failAt := func(index int, msg string) *LineError {
413			return &LineError{Status: "error", Index: index, Error: msg}
414		}
415		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
416			return &LineError{
417				Status: "error",
418				Index:  index,
419				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
420					ref, ts, formatFloat(existing), formatFloat(submitted)),
421				Conflict: &Conflict{
422					Series:    ref,
423					Timestamp: ts,
424					Existing:  existing,
425					Submitted: submitted,
426				},
427			}
428		}
429	
430		for i, item := range items {
431			pos := i + 1
432			p, err := parseSample(item)
433			if err != nil {
434				return nil, failAt(pos, err.Error())
435			}
436	
437			id := makeSeriesID(p.name, p.labels)
438			ref := SeriesRef{Name: p.name, Labels: p.labels}
439	
440			if byTS, ok := seen[id]; ok {
441				if old, ok := byTS[p.ts]; ok {
442					if old != p.value {
443						return nil, conflictAt(pos, ref, p.ts, old, p.value)
444					}
445					// 同批内重复出现且数值相同：重复，成功忽略。
446					continue
447				}
448			}
449			if sr, ok := s.series[id]; ok {
450				if old, ok := sr.points[p.ts]; ok {
451					if old != p.value {
452						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
453					}
454					// 与此前批次已写入的值相同：重复，成功忽略。
455					if seen[id] == nil {
456						seen[id] = map[int64]float64{}
457					}
458					seen[id][p.ts] = p.value
459					continue
460				}
461			}
462	
463			added++
464			if seen[id] == nil {
465				seen[id] = map[int64]float64{}
466			}
467			seen[id][p.ts] = p.value
468			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
469		}
470	
471		// 全部采样点合法且无冲突，原子提交本批新增点。
472		for _, c := range commits {
473			sr := s.series[c.id]
474			if sr == nil {
475				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
476				s.series[c.id] = sr
477			}
478			sr.points[c.ts] = c.val
479		}
480	
481		return s.snapshot(added, len(items)-added), nil
482	}
483	
484	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
485	func formatFloat(v float64) string {
486		return strconv.FormatFloat(v, 'g', -1, 64)
487	}
