489	type parsedQuery struct {
490		name   string
491		start  int64
492		end    int64
493		labels map[string]string
494	}
495	
496	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
497	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
498		q, err := parseQuery(raw)
499		if err != nil {
500			return nil, &LineError{Status: "error", Error: err.Error()}
501		}
502		if q.start > q.end {
503			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
504				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
505		}
506		return s.runQuery(q), nil
507	}
508	
509	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
510	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
511	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
512		var q parsedQuery
513		dec := json.NewDecoder(bytes.NewReader(raw))
514		dec.UseNumber()
515	
516		tok, err := dec.Token()
517		if err != nil {
518			return q, err
519		}
520		if d, ok := tok.(json.Delim); !ok || d != '{' {
521			return q, fmt.Errorf("each query must be a JSON object")
522		}
523	
524		present := make(map[string]bool)
525		for dec.More() {
526			keyTok, err := dec.Token()
527			if err != nil {
528				return q, err
529			}
530			key := keyTok.(string)
531			switch key {
532			case "op", "name", "start", "end", "labels":
533			default:
534				return q, fmt.Errorf("unknown field %q", key)
535			}
536			if present[key] {
537				return q, fmt.Errorf("duplicate field %q", key)
538			}
539			present[key] = true
540	
541			switch key {
542			case "op":
543				t, err := dec.Token()
544				if err != nil {
545					return q, err
546				}
547				op, ok := t.(string)
548				if !ok {
549					return q, fmt.Errorf(`field "op" must be a string`)
550				}
551				if op != "query" {
552					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
553				}
554			case "name":
555				t, err := dec.Token()
556				if err != nil {
557					return q, err
558				}
559				name, ok := t.(string)
560				if !ok {
561					return q, fmt.Errorf(`field "name" must be a string`)
562				}
563				if name == "" {
564					return q, fmt.Errorf(`field "name" must be a non-empty string`)
565				}
566				q.name = name
567			case "start", "end":
568				n, err := nextJSONNumber(dec, key)
569				if err != nil {
570					return q, err
571				}
572				v, err := parseJSONInt(n)
573				if err != nil {
574					return q, fmt.Errorf(`field %q: %s`, key, err)
575				}
576				if key == "start" {
577					q.start = v
578				} else {
579					q.end = v
580				}
581			case "labels":
582				t, err := dec.Token()
583				if err != nil {
584					return q, err
585				}
586				d, ok := t.(json.Delim)
587				if !ok || d != '{' {
588					return q, fmt.Errorf(`field "labels" must be an object of non-empty string keys to string values`)
589				}
590				labels := map[string]string{}
591				for dec.More() {
592					labelKeyTok, err := dec.Token()
593					if err != nil {
594						return q, err
595					}
596					labelKey := labelKeyTok.(string)
597					if labelKey == "" {
598						return q, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
599					}
600					valTok, err := dec.Token()
601					if err != nil {
602						return q, err
603					}
604					labelVal, ok := valTok.(string)
605					if !ok {
606						return q, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
607					}
608					if _, dup := labels[labelKey]; dup {
609						return q, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
610					}
611					labels[labelKey] = labelVal
612				}
613				if _, err := dec.Token(); err != nil { // 消耗 '}'
614					return q, err
615				}
616				q.labels = labels
617			}
618		}
619		if _, err := dec.Token(); err != nil { // 消耗 '}'
620			return q, err
621		}
622		if _, err := dec.Token(); err != io.EOF {
623			if err == nil {
624				return q, fmt.Errorf("unexpected content after the query object")
625			}
626			return q, err
627		}
628	
629		for _, field := range []string{"op", "name", "start", "end"} {
630			if !present[field] {
631				return q, fmt.Errorf("missing required field %q", field)
632			}
633		}
634		return q, nil
635	}
636	
637	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
638	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
639	func labelsMatch(want, stored map[string]string) bool {
640		for k, v := range want {
641			got, ok := stored[k]
642			if !ok || got != v {
643				return false
644			}
645		}
646		return true
647	}
648	
649	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
650	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
651	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
652		matched := make([]*storedSeries, 0)
653		for _, sr := range s.series {
654			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
655				continue
656			}
657			has := false
658			for ts := range sr.points {
659				if ts >= q.start && ts <= q.end {
660					has = true
661					break
662				}
663			}
664			if has {
665				matched = append(matched, sr)
666			}
667		}
668		sort.Slice(matched, func(i, j int) bool {
669			if matched[i].ref.Name != matched[j].ref.Name {
670				return matched[i].ref.Name < matched[j].ref.Name
671			}
672			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
673		})
674	
675		out := make([]QuerySeries, 0, len(matched))
676		for _, sr := range matched {
677			tsList := make([]int64, 0, len(sr.points))
678			for ts := range sr.points {
679				if ts >= q.start && ts <= q.end {
680					tsList = append(tsList, ts)
681				}
682			}
683			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
684			values := make([]float64, len(tsList))
685			for i, ts := range tsList {
686				values[i] = sr.points[ts]
687			}
688			labels := make(map[string]string, len(sr.ref.Labels))
689			for k, v := range sr.ref.Labels {
690				labels[k] = v
691			}
692			out = append(out, QuerySeries{
693				Name:    sr.ref.Name,
694				Labels:  labels,
695				Count:   len(values),
696				Average: finiteMean(values),
697			})
698		}
699		return &QueryResult{Status: "ok", Op: "query", Series: out}
700	}
701	
702	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
703	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
704	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
705	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
706	// 只有一个点时结果就是该点的值。
707	func finiteMean(values []float64) float64 {
708		sum := new(big.Rat)
709		r := new(big.Rat)
710		for _, v := range values {
711			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
712			sum.Add(sum, r.SetFloat64(v))
713		}
714		sum.Quo(sum, r.SetInt64(int64(len(values))))
715		return ratToFloat64NearestEven(sum)
716	}
717	
718	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
719	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
720	func ratToFloat64NearestEven(x *big.Rat) float64 {
721		if x.Sign() == 0 {
722			return 0
723		}
724		num := new(big.Int).Set(x.Num())
725		den := x.Denom()
726		neg := num.Sign() < 0
727		if neg {
728			num.Neg(num)
729		}
730	
731		// e 满足 2^e <= num/den < 2^(e+1)。
732		e := floorLog2Rat(num, den)
733		var m *big.Int
734		scale := 0
735		if e >= -1022 {
736			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
737			scale = e - 52
738			m = roundScaledRatio(num, den, scale)
739			if m.BitLen() == 54 {
740				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
741				m.Rsh(m, 1)
742				scale++
743			}
744		} else {
745			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
746			scale = -1074
747			m = roundScaledRatio(num, den, scale)
748		}
749		// m < 2^53，可以精确放入 int64 与 float64。
750		f := math.Ldexp(float64(m.Int64()), scale)
751		if neg {
752			return -f
753		}
754		return f
755	}
756	
757	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
758	func floorLog2Rat(num, den *big.Int) int {
759		k := num.BitLen() - den.BitLen()
760		var t big.Int
761		if k >= 0 {
762			t.Lsh(den, uint(k))
763			if num.Cmp(&t) >= 0 {
764				return k
765			}
766			return k - 1
767		}
768		t.Lsh(num, uint(-k))
769		if t.Cmp(den) >= 0 {
770			return k
771		}
772		return k - 1
773	}
774	
775	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
776	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
777		n := new(big.Int).Set(num)
778		d := new(big.Int).Set(den)
779		if scale >= 0 {
780			d.Lsh(d, uint(scale))
781		} else {
782			n.Lsh(n, uint(-scale))
783		}
784		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
785		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
786		case 1:
787			q.Add(q, big.NewInt(1))
788		case 0:
789			if q.Bit(0) == 1 {
790				q.Add(q, big.NewInt(1))
791			}
792		}
793		return q
794	}
795	
796	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
797	func (r SeriesRef) String() string {
798		var b strings.Builder
799		b.WriteString(r.Name)
800		b.WriteByte('{')
801		for i, p := range sortedPairs(r.Labels) {
802			if i > 0 {
803				b.WriteByte(',')
804			}
805			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
806		}
807		b.WriteByte('}')
808		return b.String()
809	}
810	
811	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
812	// 序列内按时间戳升序。
813	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
814		views := make([]SeriesView, 0, len(s.series))
815		for _, sr := range s.series {
816			tsList := make([]int64, 0, len(sr.points))
817			for ts := range sr.points {
818				tsList = append(tsList, ts)
819			}
820			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
821			points := make([]Point, len(tsList))
822			for i, ts := range tsList {
823				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
824			}
825			labels := make(map[string]string, len(sr.ref.Labels))
826			for k, v := range sr.ref.Labels {
827				labels[k] = v
828			}
829			views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
830		}
831		sort.Slice(views, func(i, j int) bool {
832			if views[i].Name != views[j].Name {
833				return views[i].Name < views[j].Name
834			}
835			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
836		})
837		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
838	}
839

