212			{`[{"name":"m","value":1}]`, 1},                                          // 缺 timestamp
213			{`[{"name":"m","timestamp":1}]`, 1},                                      // 缺 value
214			{`[{"name":"","timestamp":1,"value":1}]`, 1},                             // 空指标名
215			{`[{"name":7,"timestamp":1,"value":1}]`, 1},                              // name 类型错误
216			{`[{"name":"m","timestamp":true,"value":1}]`, 1},                         // timestamp 非数字
217			{`[{"name":"m","timestamp":1.0,"value":1}]`, 1},                          // timestamp 非整数
218			{`[{"name":"m","timestamp":"1","value":1}]`, 1},                          // timestamp 字符串
219			{`[{"name":"m","timestamp":1,"value":"1"}]`, 1},                          // value 字符串
220			{`[{"name":"m","timestamp":1,"value":true}]`, 1},                         // value 布尔
221			{`[{"name":"m","timestamp":1,"value":1e999}]`, 1},                        // value 超出 float64
222			{`[{"name":"m","timestamp":9223372036854775808,"value":1}]`, 1},          // timestamp 超 int64
223			{`[{"name":"m","timestamp":-9223372036854775809,"value":1}]`, 1},         // timestamp 低于 int64
224			{`[{"name":"m","timestamp":1,"value":1,"zone":"x"}]`, 1},                 // 未知字段
225			{`[{"name":"m","timestamp":1,"value":1,"labels":[]}]`, 1},                // labels 非对象
226			{`[{"name":"m","timestamp":1,"value":1,"labels":null}]`, 1},              // labels 为 null
227			{`[{"name":"m","timestamp":1,"value":1,"labels":{"": "x"}}]`, 1},         // 空标签键
228			{`[{"name":"m","timestamp":1,"value":1,"labels":{"k": 2}}]`, 1},          // 标签值非字符串
229			{`[{"name":"m","timestamp":1,"value":1},{"name":7}]`, 2},                 // 错误位置从 1 开始
230			{`[{"name":"m","timestamp":1,"value":1,"labels":{"a":"1","a":"2"}}]`, 1}, // 重复标签键
231		}
232		for _, tc := range cases {
