548		res3 := mustQuery(t, store3, `{"op":"query","name":"m","start":0,"end":100}`)
549		if res3.Series[0].Average != avg {
550			t.Fatalf("average depends on write order: %v vs %v", res3.Series[0].Average, avg)
551		}
552	}
553	
554	func TestQueryAverageExactAfterCancellation(t *testing.T) {
555		store := NewMetricStore()
556		mustOK(t, store, `[
557			{"name":"m","timestamp":1,"value":1e16},
558			{"name":"m","timestamp":2,"value":1},
559			{"name":"m","timestamp":3,"value":-1e16}
560		]`)
561		res := mustQuery(t, store, `{"op":"query","name":"m","start":1,"end":3}`)
562		if len(res.Series) != 1 {
563			t.Fatalf("series = %+v, want exactly one", res.Series)
564		}
565		s0 := res.Series[0]
566		if s0.Count != 3 {
567			t.Fatalf("count = %d, want 3", s0.Count)
568		}
569		// 精确总和为 1，平均值为 1/3 舍入后的最近 float64。
570		if s0.Average != 1.0/3.0 {
571			t.Fatalf("average = %v, want %v", s0.Average, 1.0/3.0)
572		}
573		b, _ := json.Marshal(s0.Average)
574		if string(b) != "0.3333333333333333" {
575			t.Fatalf("average JSON = %s, want 0.3333333333333333", b)
576		}
577	}
