package darksafe

import "testing"

// 调用方改写跨批冲突返回对象中的标签，不得影响已存储序列身份。
func TestScratchConflictResultIsIndependent(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":1,"labels":{"host":"a"}}]`)

	lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
	c := lerr.Conflict
	if c.Series.Name != "cpu" || c.Series.Labels["host"] != "a" ||
		c.Timestamp != 1000 || c.Existing != 1 || c.Submitted != 2 || lerr.Index != 1 {
		t.Fatalf("conflict detail wrong: %+v", c)
	}

	// 调用方为整理错误信息而改写手中的冲突结果。
	c.Series.Labels["host"] = "b"
	c.Series.Labels["extra"] = "z"
	delete(c.Series.Labels, "host")
	c.Series.Name = "mem"

	// host=a 仍能查到原成功点，数量与均值正确。
	q := mustQueryScratch(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"labels":{"host":"a"}}`)
	if len(q.Series) != 1 || q.Series[0].Count != 1 || q.Series[0].Average != 1 {
		t.Fatalf("host=a query after edit = %+v", q.Series)
	}
	// host=b 不能因编辑而匹配。
	q = mustQueryScratch(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"labels":{"host":"b"}}`)
	if len(q.Series) != 0 {
		t.Fatalf("host+b leaked: %+v", q.Series)
	}
	// 快照仍反映真实存储。
	snap := mustOK(t, store, `[]`)
	if len(snap.Series) != 1 || snap.Series[0].Labels["host"] != "a" || len(snap.Series[0].Labels) != 1 {
		t.Fatalf("snapshot tainted: %+v", snap.Series)
	}
	// 后续写入：同值仍按重复处理，不同值仍按冲突判断且 existing 为原值 1。
	dup := mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":1.0,"labels":{"host":"a"}}]`)
	if dup.Added != 0 || dup.Duplicates != 1 {
		t.Fatalf("dedup broken after edit: %+v", dup)
	}
	lerr2 := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":3,"labels":{"host":"a"}}]`)
	if lerr2.Conflict.Existing != 1 || lerr2.Conflict.Submitted != 3 ||
		lerr2.Conflict.Series.Labels["host"] != "a" {
		t.Fatalf("second conflict wrong: %+v", lerr2.Conflict)
	}
}

// 无标签序列：在返回的空标签集合里加键，不得给已有序列补标签。
func TestScratchConflictUnlabeledIndependence(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"m","timestamp":1,"value":1}]`)
	lerr := mustFail(t, store, `[{"name":"m","timestamp":1,"value":2}]`)
	lerr.Conflict.Series.Labels["host"] = "b"

	q := mustQueryScratch(t, store, `{"op":"query","name":"m","start":0,"end":2}`)
	if len(q.Series) != 1 || len(q.Series[0].Labels) != 0 {
		t.Fatalf("unlabeled series gained label: %+v", q.Series)
	}
	q = mustQueryScratch(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"host":"b"}}`)
	if len(q.Series) != 0 {
		t.Fatalf("fabricated label matched: %+v", q.Series)
	}
}

// 空字符串标签值序列与缺键序列在冲突结果被编辑后仍保持区别。
func TestScratchConflictEmptyValuePreserved(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"m","timestamp":1,"value":1,"labels":{"zone":""}}]`)
	lerr := mustFail(t, store, `[{"name":"m","timestamp":1,"value":2,"labels":{"zone":""}}]`)
	if v, ok := lerr.Conflict.Series.Labels["zone"]; !ok || v != "" {
		t.Fatalf("empty-value label not preserved in conflict: %+v", lerr.Conflict.Series.Labels)
	}
	delete(lerr.Conflict.Series.Labels, "zone")
	// 存储序列仍带空值 zone 键：zone="" 查询命中，无标签查询也只有一条带空值的序列。
	q := mustQueryScratch(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":""}}`)
	if len(q.Series) != 1 || q.Series[0].Average != 1 {
		t.Fatalf("empty-value distinction lost: %+v", q.Series)
	}
}

// 批内冲突报告本批先出现的值，且整批不生效；编辑其结果不影响存储。
func TestScratchWithinBatchConflictIndependence(t *testing.T) {
	store := NewMetricStore()
	lerr := mustFail(t, store, `[
		{"name":"n","timestamp":1,"value":1,"labels":{"host":"a"}},
		{"name":"n","timestamp":1,"value":2,"labels":{"host":"a"}}
	]`)
	if lerr.Index != 2 || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 2 {
		t.Fatalf("within-batch conflict wrong: %+v", lerr.Conflict)
	}
	lerr.Conflict.Series.Labels["host"] = "b"
	if got := len(mustOK(t, store, `[]`).Series); got != 0 {
		t.Fatalf("failed batch wrote data: %d series", got)
	}
}

func mustQueryScratch(t *testing.T, store *MetricStore, line string) *QueryResult {
	t.Helper()
	res, err := store.QueryLine(line)
	if err != nil {
		t.Fatalf("query failed: %+v", err)
	}
	return res
}

